code_snippets.parse_list:
def parse(self, response):
    items = response.css('ul li')
    for item in items:
        title = item.css('a::text').get()
        detail_url = response.urljoin(item.css('a::attr(href)').get())
        yield scrapy.Request(detail_url, callback=self.parse_detail, meta={'title': title})

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.meta['title']
    # 示例：提取PDF链接
    pdf_links = response.css('a[href$=".pdf"]::attr(href)').getall()
    pdf_links = [response.urljoin(url) for url in pdf_links]
    yield {
        'title': title,
        'pdf_links': pdf_links
    }
